import openpyxl
wb = openpyxl.load_workbook('sales_data.xlsx')
for ws in wb.worksheets:
    print(f"Sheet: {ws.title}, dims: {ws.dimensions}, max_row: {ws.max_row}, max_col: {ws.max_column}")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 10)):
        print([(c.coordinate, c.value) for c in row])

import importlib
for mod in ['pandas', 'openpyxl', 'xlsxwriter', 'xlrd', 'odf']:
    try:
        importlib.import_module(mod)
        print(mod, 'OK')
    except Exception as e:
        print(mod, 'MISSING', e)

